CREATE OR REPLACE FUNCTION public.command_supply_route(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r supply_requests; stock inventory_items; pending integer; pid uuid; chief uuid; BEGIN SELECT * INTO r FROM supply_requests WHERE id=_id FOR UPDATE; IF r.workflow_kind<>'Command' OR r.approval_status<>'Approved' OR r.stage>=8 THEN RETURN; END IF; IF r.item_id IS NOT NULL THEN SELECT * INTO stock FROM inventory_items WHERE id=r.item_id FOR UPDATE; SELECT coalesce(sum(reserved_quantity),0) INTO pending FROM supply_requests WHERE item_id=r.item_id AND id<>r.id AND stage<8 AND approval_status='Approved'; END IF; IF coalesce(stock.quantity,0)-coalesce(pending,0)>=r.quantity AND r.item_id IS NOT NULL THEN UPDATE supply_requests SET stage=5,collection_status='Prepare Supply',reserved_quantity=r.quantity WHERE id=r.id; PERFORM command_notify(r.requested_by,'Requested item is now available for pickup preparation.',r.request_number,r.id||':stock-available'); FOR chief IN SELECT user_id FROM user_roles WHERE role='storekeeper' LOOP PERFORM command_notify(chief,'Prepare Supply',r.request_number||' · '||r.item_name,r.id||':prepare'); END LOOP; ELSE UPDATE supply_requests SET collection_status='Purchase Required',reserved_quantity=0 WHERE id=r.id; IF r.procurement_id IS NULL THEN SELECT e.user_id INTO chief FROM reporting_lines l JOIN officers e ON e.id=l.officer_id WHERE l.kind='Chief Procurement Officer' AND l.office_id IS NULL; IF chief IS NULL THEN SELECT user_id INTO chief FROM user_roles WHERE role='procurement_admin' ORDER BY user_id LIMIT 1; END IF; IF chief IS NOT NULL THEN INSERT INTO procurement_funding(section_id,item_description,quantity,requested_by,priority,justification,unit,estimated_cost) VALUES(r.section_id,r.item_name,r.quantity,chief,CASE r.priority WHEN 'Urgent' THEN 'Emergency' WHEN 'Normal' THEN 'Medium' ELSE r.priority END,'Supply shortage: '||r.request_number||' · '||coalesce(r.justification,''),r.unit,coalesce(stock.unit_cost,0)*r.quantity) RETURNING id INTO pid; INSERT INTO request_items(request_id,description,quantity,unit,estimated_unit_cost) VALUES(pid,r.item_name,r.quantity,r.unit,coalesce(stock.unit_cost,0)); UPDATE supply_requests SET procurement_id=pid WHERE id=r.id; END IF; END IF; FOR chief IN SELECT user_id FROM user_roles WHERE role IN ('procurement_officer','procurement_admin') LOOP PERFORM command_notify(chief,'Purchase Required',r.request_number||' · '||r.item_name,r.id||':purchase'); END LOOP; PERFORM command_notify(r.requested_by,'Supply requires procurement',r.request_number,r.id||':shortage'); END IF; END $$;